head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf73010";
scwin.editor = undefined;
scwin.fn_chkDup = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf73010' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fn_chkDup = scwin.tx_fn_chkDup;
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf73010.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name relLawDtlForm_onsubmit
 * @description relLawDtlForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.relLawDtlForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73010.relLawDtlForm_onsubmit' }); }
};

/**
 * @method
 * @name ipt_relLawDtlNm_onchange
 * @description ipt_relLawDtlNm 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_relLawDtlNm_onchange = function(e){
    try {
        scwin.changeText();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73010.ipt_relLawDtlNm_onchange' }); }
};

/**
 * @method
 * @name input_26_onclick
 * @description 「중복확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_26_onclick = function(e){
    try {
        scwin.fn_chkDup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73010.input_26_onclick' }); }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf73010.btn_save_onclick' }); }
};

/**
 * @method
 * @name btn_closeFrame_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closeFrame_onclick = function(e){
    try {
        scwin.closeFrame()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73010.btn_closeFrame_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_saveReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_chkDup
 * @description chk Dup 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_chkDup = async function () {
    const sbmOptions = {
        id: "tx_fn_chkDup",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_chkDupReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name closeFrame
 * @description close Frame 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeFrame = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    $c.win.closePopup();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if ($c.util.getComponent('ipt_dupChkYn').getValue() !== 'Y') {
        await $c.win.alert("단위조항 중복확인 후 저장이 가능합니다.");
        return;
    }
    let sprtRoomNo = $('#slc_junmoon option:selected').val();
    if (sprtRoomNo.length === 0) {
        await $c.win.alert("법규전문을 선택해 주시기 바랍니다.");
        return;
    }
    if (!await $c.win.confirm("저장하시겠습니까?")) {
        return;
    }
    sprtRoomNo = $('#slc_junmoon option:selected').val();
    sprtRoomNo = sprtRoomNo.split("_")[0];
    $c.util.getComponent('ipt_sprtRoomNo').setValue(sprtRoomNo);
    $c.util.getComponent('ipt_relLawDtlContn').setValue(DEXT5.getBodyValue("dext5editor1"));
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name changeText
 * @description change Text 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeText = function () {
    $c.util.getComponent('ipt_dupChkYn').setValue("N");
    setBtnEnable($('#dupBtn'));
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
